local a=base
local lo=-1
local hi=2
local out=np.full({2,3},7,{dtype="datetime64[h]",order="C"})
local where=np.array({{true,false,true},{true,false,true}},"bool")
local ok,result=pcall(function()return np.clip(a,lo,hi,{out=out,where=where})end)
assert(ok==false,"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: acceptance"..": "..tostring(result))
eq(np.astype(out,"int64"):tolist(),{{7,7,7},{7,7,7}},"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: output: ticks")
eq(out.shape,{2,3},"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: output: shape")
eq(out.strides,{24,8},"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: output: strides")
eq(out.dtype,"datetime64[h]","clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: output: dtype")
eq(a:tolist(),{{0,1,2},{3,4,5}},"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: input: values")
eq(a.shape,{2,3},"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: input: shape")
eq(a.strides,{12,4},"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: input: strides")
eq(a.dtype,"uint32","clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: input: dtype")
eq(base:tolist(),{{0,1,2},{3,4,5}},"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: backing: values")
eq(base.shape,{2,3},"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: backing: shape")
eq(base.strides,{12,4},"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: backing: strides")
eq(base.dtype,"uint32","clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/out/datetime64[h]/maskTrue: backing: dtype")
cases=cases+1
end
