eq(out.dtype,"uint32","clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/inplace/float64/maskFalse: output: dtype")
eq(a:tolist(),{{0,1,2},{2,2,2}},"clip/uint32(2, 3)/base/['-1', '2']/weak(True, True)/inplace/float64/maskFalse: input: values")
