local a=base
local lo=-1
local hi=2
local out=np.full({a.size+1},7,"float64")
local ok,result=pcall(function()return np.clip(a,lo,hi,{out=out})end)
assert(ok==false,"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: acceptance"..": "..tostring(result))
eq(out:tolist(),{7.0,7.0,7.0,7.0,7.0,7.0,7.0},"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: output: values")
eq(out.shape,{7},"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: output: shape")
eq(out.strides,{8},"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: output: strides")
eq(out.dtype,"float64","clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: output: dtype")
eq(np.logical_and(np.signbit(out),np.equal(out,0)):tolist(),{false,false,false,false,false,false,false},"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: output: signed zero")
eq(np.astype(a,"U40"):tolist(),{{"0","1","2"},{"3","4","5"}},"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: input: integer strings")
eq(a.shape,{2,3},"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: input: shape")
eq(a.strides,{24,8},"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: input: strides")
eq(a.dtype,"uint64","clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: input: dtype")
eq(np.astype(base,"U40"):tolist(),{{"0","1","2"},{"3","4","5"}},"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: backing: integer strings")
eq(base.shape,{2,3},"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: backing: shape")
eq(base.strides,{24,8},"clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: backing: strides")
eq(base.dtype,"uint64","clip/uint64(2, 3)/base/['-1', '2']/weak(True, True)/badshape/float64/maskFalse: backing: dtype")
cases=cases+1
end
